DROP TABLE IF EXISTS `tb_carne`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_carne` (
  `idcarne` int unsigned NOT NULL AUTO_INCREMENT,
  `tb_turmas_idTurmas` int unsigned NOT NULL,
  `tb_turmas_Mensalidade` decimal(11,2) unsigned NOT NULL,
  `tb_aluno_idAluno` int unsigned NOT NULL,
  `RA` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `parcelas` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `Ano_Letivo` varchar(4) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `ValorPGTO` decimal(11,2) NOT NULL,
  `valor_prestacao` decimal(11,2) NOT NULL,
  `valor_Acordo` decimal(11,2) NOT NULL,
  `codbarras` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `data_pagamento` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `status_pagamento` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `obs_pagamento` varchar(10000) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `obs_do_acordo` mediumtext CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `Meses` varchar(15) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `Digito_verificador` varchar(2) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `Carteira` varchar(4) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `Acordo` varchar(4) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `Data_venc` varchar(11) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `forma_pgto` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  PRIMARY KEY (`idcarne`),
  KEY `tb_carne_tb_turmas_idturmas_foreign` (`tb_turmas_idTurmas`)
) ENGINE=InnoDB AUTO_INCREMENT=28184 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
