--
-- Table structure for table `tb_receitas`
--

DROP TABLE IF EXISTS `tb_receitas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_receitas` (
  `idReceita` int unsigned NOT NULL AUTO_INCREMENT,
  `tb_categoria_idCategoria` int unsigned NOT NULL,
  `NomeReceita` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `DataReceita` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ReceitaValor` decimal(20,2) NOT NULL,
  `StatusReceita` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ObsReceita` text COLLATE utf8mb4_unicode_ci,
  `imgReceita` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idReceita`),
  KEY `tb_receitas_tb_categoria_idcategoria_foreign` (`tb_categoria_idCategoria`),
